+const KEY_FLOOR = 32;
+const PRESENCE_PATH = "/a2a/agents/presence";
+
+/** `<host>-<port>`, same spelling as hub-key.mjs. Reimplemented here; session-start is not imported. */
+export function hubIdForUrl(hubUrl: string): string {
+  const u = new URL(hubUrl);
+  const port = u.port || (u.protocol === "https:" ? "443" : "80");
+  return `${u.hostname.toLowerCase()}-${port}`;
+}
+
+/**
+ * Per-agent key file: $A2A_KEY_DIR or ~/.a2a-hub/keys / <hub-id> / <hub_name>.key.
+ * Default name is this seat's hub_name (cursor-builder on this checkout).
+ */
+export function resolveSeatKeyPath(input: {
+  hubUrl: string;
+  hubName: string;
+  keyDir?: string;
+  home?: string;
+}): string {
+  const dir = input.keyDir && input.keyDir.trim()
+    ? input.keyDir
+    : join(input.home ?? homedir(), ".a2a-hub", "keys");
+  return join(dir, hubIdForUrl(input.hubUrl), `${input.hubName}.key`);
+}
+
+export interface CensusAgent {
+  name: string;
+  seatState: string;
+}
+
+export interface CensusResult {
+  source: "hub-presence";
+  timestamp: string;
+  available: boolean;
+  /** Set when available is false. Always starts with "census unavailable:". */
+  reason: string | null;
+  agents: CensusAgent[];
+  /** SIA names (and their -waker siblings) whose seatState is working. */
+  busySia: string[];
+  samples: number;
+}
+
+export interface ReadCensusOptions {
+  hubUrl: string;
+  keyPath: string | undefined;
+  siaSeatNames: readonly string[];
+  fetchFn?: typeof fetch;
+  timeoutMs?: number;
+  /** Delay between the two samples. Tests pass 0. */
+  gapMs?: number;
+  now?: () => string;
+}
+
+function unavailable(reason: string, timestamp: string, samples: number): CensusResult {
+  const text = reason.startsWith("census unavailable:") ? reason : `census unavailable: ${reason}`;
+  return {
+    source: "hub-presence",
+    timestamp,
+    available: false,
+    reason: text,
